repl(generic,
'''function damageAllOtherFollowers(session, playerIndex, source, amount, destroyFollower) {''',
'''function damageOpposingFollower(session, playerIndex, source, instanceId, amount, destroyFollower) {\n  if (!instanceId) return false;\n  const enemyIndex = 1 - playerIndex;\n  const target = session.findBoardCard(enemyIndex, instanceId);\n  if (!target || cardType(target) !== "follower") return false;\n  const damage = Math.max(0, Number(amount) || 0);\n  session.damageFollower(enemyIndex, target.instanceId, damage, {\n    actor: playerIndex,\n    source,\n    reason: "ability",\n    resolveDeath: false\n  });\n  const live = session.findBoardCard(enemyIndex, target.instanceId);\n  if (live && currentDefense(live) <= 0) {\n    destroyFollower?.(session, enemyIndex, live.instanceId, {\n      actor: playerIndex,\n      source,\n      reason: "ability",\n      byAbility: true\n    });\n  }\n  return true;\n}\n\nfunction destroyOpposingFollower(session, playerIndex, source, instanceId, destroyFollower) {\n  if (!instanceId) return false;\n  const enemyIndex = 1 - playerIndex;\n  const target = session.findBoardCard(enemyIndex, instanceId);\n  if (!target || cardType(target) !== "follower") return false;\n  return Boolean(destroyFollower?.(session, enemyIndex, target.instanceId, {\n    actor: playerIndex,\n    source,\n    reason: "ability",\n    byAbility: true,\n    abilityDestroy: true\n  }));\n}\n\nfunction damageAllOtherFollowers(session, playerIndex, source, amount, destroyFollower) {''')

resolver = "src/core/rulesets/svwb/effect-resolver.js"
repl(resolver,
'''export function resolveWorldsBeyondTrigger(session, { trigger, playerIndex, source, targetInstanceId = null, discardInstanceId = null, mode = null, antecedentInstanceIds = [] }) {\n  if (!source?.card) return { applied: false, unresolved: false, text: "" };''',
'''export function resolveWorldsBeyondTrigger(session, { trigger, playerIndex, source, targetInstanceId = null, discardInstanceId = null, mode = null, antecedentInstanceIds = [], opposingFollowerInstanceId = null }) {\n  if (!source?.card) return { applied: false, unresolved: false, text: "" };\n  if (trigger === "strike" && !opposingFollowerInstanceId && hasFollowerStrikeOnly(source)) {\n    return { applied: false, unresolved: false, text: "", followerStrikeSkipped: true };\n  }''')
